var i=[{title:`Ein wiederholbares Maß wählen`,text:`Gute Optionen sind, wie weit du in einer festgelegten Zeit gehst, wie lange eine vertraute Strecke dauert, ob du eine festgelegte Intervalleinheit abschließt oder deine Herzfrequenz bei einem bequemen festen Tempo. Die Session-RPE ergänzt diese Zahlen, besonders wenn du keinen Herzfrequenzmesser hast.`},{title:`Testbedingungen ähnlich halten`,text:`Temperatur, Steigungen, Schlaf, Koffein, Ausrüstung und Erholung beeinflussen alle die Leistung. Vergleiche, wenn möglich, dieselbe Laufbandeinstellung, denselben Radwiderstand oder dieselbe Strecke im Freien. Eine niedrigere Herzfrequenz bedeutet nicht immer, dass du fitter bist, denn auch Medikamente und Messfehler können den Wert verändern.`},{title:`Beispiel`,text:`Ein Anfänger beginnt, indem er zwei Minuten Gehen mit einer Minute leichtem Joggen abwechselt. Wochen später schafft er mehr Jogging-Intervalle bei ähnlicher Anstrengung. Eine andere Person fährt dieselbe Radstrecke, und sie fühlt sich leichter an, obwohl die Durchschnittsgeschwindigkeit gleich bleibt.`},{title:`Wie oft du testen solltest`,text:`Ein geplanter Check alle paar Wochen zeigt Trends, während deine normalen Einheiten aufs Training konzentriert bleiben. Ein plötzlicher Leistungsabfall kann von Ermüdung oder Krankheit kommen, und er muss nicht bedeuten, dass du deine Kondition dauerhaft verloren hast.`},{title:`TrainUp nutzen`,text:`Nach jedem Training bewertest du die Anstrengung von 1 bis 10, und der Verlauf zeigt deine durchschnittliche Anstrengung und ein Diagramm über 4 Wochen. Achte auf den Trend über Wochen. Ein einzelner Herzfrequenz- oder Geschwindigkeitswert kann deine Herz-Kreislauf-Gesundheit weder diagnostizieren noch garantieren.`}];var t=[{label:`NHS: Gehen für die Gesundheit`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`},{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};